function prepareInWorker(count,bytes) {
  if(typeof Worker==='undefined')return Promise.reject(new Error('Dedicated Worker unavailable; choose the main-thread lane explicitly'));
  return new Promise((resolve,reject)=>{
    const id=++preparationSequence,worker=new Worker(new URL('./lab-worker.2078a31465096c94.mjs',import.meta.url),{type:'module'});
    let settled=false;
    const finish=(error,result)=>{if(settled)return;settled=true;clearTimeout(deadline);worker.terminate();preparationCancel=null;error?reject(error):resolve(result);};
    const deadline=setTimeout(()=>finish(new Error('Worker preparation exceeded its 30-second budget')),30000);
    preparationCancel=()=>finish(new Error('Stopped during data preparation; previous workload and completed evidence retained.'));
    worker.onerror=()=>finish(new Error('Worker preparation failed; no fallback or partial success accepted'));
    worker.onmessage=event=>{if(event.data?.id!==id)return;if(event.data.ok!==true){finish(new Error(String(event.data.error||'Worker preparation failed')));return;}finish(null,event.data.result);};
    worker.postMessage({id,count,bytes});
  });
}
const observed={longtask:[], 'long-animation-frame':[]};
const inputEvents=[];
const supported=PerformanceObserver.supportedEntryTypes||[];
for(const type of Object.keys(observed)){if(supported.includes(type)){new PerformanceObserver(list=>{for(const e of list.getEntries())if(evidence)retainWindowObservation(observed[type],{start_ms:e.startTime,duration_ms:e.duration,render_start_ms:Number.isFinite(e.renderStart)?e.renderStart:null,style_layout_start_ms:Number.isFinite(e.styleAndLayoutStart)?e.styleAndLayoutStart:null,blocking_duration_ms:Number.isFinite(e.blockingDuration)?e.blockingDuration:null,script_duration_ms:e.scripts?Array.from(e.scripts).reduce((sum,s)=>sum+s.duration,0):null},evidence.performance_start_ms,evidence.performance_end_ms??performance.now());}).observe({type,buffered:false});}}
