$('cancel').addEventListener('click',()=>{stop=true;$('cancel').disabled=true;if(preparationCancel){preparationCancel();$('status').textContent='Stopping data preparation; previous completed evidence retained.';}else $('status').textContent='Stopping after the current sample; evidence will be retained.';});
